create or replace function public.record_media_download(p_post_id uuid,p_media_type text) returns void language plpgsql security definer set search_path=public as $$ declare owner uuid; label text; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if p_media_type not in ('image','video') then raise exception 'Invalid media type'; end if; select author_id into owner from public.posts where id=p_post_id; if owner is null then raise exception 'Post not found'; end if; label:=case when p_media_type='video' then 'video' else 'image' end; insert into public.notifications(recipient_id,kind,payload) values(auth.uid(),'media_downloaded',jsonb_build_object('message','You downloaded this '||label||'.','entity_type','post','entity_id',p_post_id::text,'media_type',p_media_type)); end; $$; grant execute on function public.record_media_download(uuid,text) to authenticated;
